{
  "references": [
    {
      "id": "R1",
      "summary_ko": "사람의 입 모양이 말과 일치하지 않음."
    },
    {
      "id": "R2",
      "summary_ko": "여성의 손이 개의 귀와 뒤엉키듯 겹쳐 보임."
    },
    {
      "id": "R3",
      "summary_ko": "핏불의 다정한 본성을 제대로 보여주지 못함."
    },
    {
      "id": "R4",
      "summary_ko": "프롬프트 요구와 달리 들판에 앉아 있는 여성과 개만 나타남."
    },
    {
      "id": "R5",
      "summary_ko": "개가 핏불 품종과 닮지 않음."
    },
    {
      "id": "R6",
      "summary_ko": "개의 음영이나 조명이 여성과 맞지 않아 비현실적이고 디지털로 합성한 것 같음."
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "여성의 오른손에 분홍색 물체가 간헐적으로 나타났다 사라짐."
    },
    {
      "id": "C2",
      "summary_ko": "여성의 손과 팔이 제스처 도중 왜곡되고 흐릿해지며 구조적 형태를 잃음."
    },
    {
      "id": "C3",
      "summary_ko": "개의 꼬리 끝부분이 흔들릴 때 형태, 불투명도, 연결성이 불일치하게 변함."
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "입 모양과 오디오 불일치에 대한 설명과 손에 분홍색 물체가 깜빡이는 현상으로 대상과 오류 내용이 다릅니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "입 모양 불일치와 손 및 팔의 구조적 왜곡 현상으로 대상과 결함 유형이 다릅니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "사람의 입 모양 문제와 개 꼬리 팁의 왜곡 문제로 대상과 결함이 완전히 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "개의 귀와 손이 뒤엉키는 결함과 손에 분홍색 물체가 나타났다 사라지는 현상은 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C2",
      "verdict": "uncertain",
      "reason_ko": "둘 다 여성의 손 부위 왜곡을 다루고 있으나, 귀와 얽히는 구체적 접촉 결함과 손/팔 전반의 왜곡 설명이 완전히 일치하는지 불확실합니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "손과 귀의 상호작용 문제와 개 꼬리의 흔들림 중 왜곡 문제로 서로 다릅니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "핏불의 성격 묘사에 대한 주관적 불만과 손의 물체 깜빡임 결함으로 전혀 다릅니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "내용적 묘사 불만과 손/팔 왜곡이라는 시각적 생성 오류는 서로 다릅니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "영상의 성격적 연출 불만과 개 꼬리의 형태 변형 결함은 서로 다릅니다."
    },
    {
      "reference_id": "R4",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "프롬프트 충실도 문제와 특정 시각적 깜빡임 결함으로 서로 다릅니다."
    },
    {
      "reference_id": "R4",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "프롬프트 지시 불이행에 대한 비판과 신체 부위 왜곡 현상은 서로 다릅니다."
    },
    {
      "reference_id": "R4",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "프롬프트 충실도 관련 언급과 개의 꼬리 시각 결함은 서로 무관합니다."
    },
    {
      "reference_id": "R5",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "개의 품종 외형 문제와 여성의 손에 발생하는 시각적 아티팩트는 서로 다릅니다."
    },
    {
      "reference_id": "R5",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "개의 품종 불일치 문제와 여성의 손/팔 왜곡은 서로 다릅니다."
    },
    {
      "reference_id": "R5",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "품종 불일치에 대한 지적과 개 꼬리 끝부분의 물리적 왜곡은 서로 다른 내용입니다."
    },
    {
      "reference_id": "R6",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "개의 조명 및 합성 부자연스러움과 손에 물체가 나타나는 결함은 대상과 내용이 다릅니다."
    },
    {
      "reference_id": "R6",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "개 전체의 조명 불일치 문제와 여성 손/팔의 형태 붕괴 문제는 서로 다릅니다."
    },
    {
      "reference_id": "R6",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "개의 전반적인 조명/음영 불일치 지적과 꼬리 끝부분의 형태/투명도 왜곡은 서로 다른 결함입니다."
    }
  ]
}
